javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let results = api.data.fetch_knowledge_gaps_task_type_data.results;
    let canReadItems = results.filter(item => item.canRead && item.isGenAIPluginActive);
    let itemsWithGaps = canReadItems.filter(item => item.isSkillActive && item.gapSize > 0);
    let value = itemsWithGaps.length ? itemsWithGaps[0].id : (canReadItems.length ? canReadItems[0].id : "");
    return {
        propName: "gapTaskType",
        value: value
    };
})

